endproperty

property p_remaining_load_behavior;
    @(posedge clk) disable iff (rst) (load == 1'b1) |-> (remaining == 3'd7);
endproperty

property p_remaining_tick_behavior;
    @(posedge clk) disable iff (rst) (load == 1'b0) && (tick == 1'b1) && (remaining > 3'd0) |-> (remaining == remaining - 3'd1);
endproperty

property p_remaining_stable;
    @(posedge clk) disable iff (rst) remaining ##1 remaining;
endproperty

property p_expired_behavior;
    @(posedge clk) disable iff (rst) (remaining == 3'd0) |-> expired == 1'b1;
endproperty

a_remaining_non_negative: assert property (p_remaining_non_negative);
a_remaining_load_behavior: assert property (p_remaining_load_behavior);
a_remaining_tick_behavior: assert property (p_remaining_tick_behavior);
a_remaining_stable: assert property (p_remaining_stable);
a_expired_behavior: assert property (p_expired_behavior);
